const N = 10 ** 9 + 7;
const mod = 998244353;

const inv = (x: number): number => {
    let res = 1, pow = N - 2;
    while (pow > 0) {
        if (pow % 2 === 1) res = (res * x) % mod;
        x = (x * x) % mod;
        pow >>= 1;
    }
    return res;
};

const nCr = (x: number, y: number): number => {
    const f = Array(x + 1).fill(1);
    for (let i = 2; i <= x; i++) f[i] = (f[i - 1] * i) % N;
    return (f[x] * inv((f[y] * f[x - y]) % N)) % N;
};

