typedef long long ll;
const ll mod = 998244353;
const ll N = 1e9 + 7;

ll gcd(ll a, ll b) {
    while (b != 0) {
        ll t = b;
        b = a % b;
        a = t;
    }
    return a;
}

ll lcm(ll x, ll y) {
    return (x * y) / gcd(x, y);
}

ll inv(ll x) {
    return pow(x, N - 2, N);
}

ll nCr(ll x, ll y) {
    static vector<ll> f(N + 1, 1);
    for (ll i = 2; i <= N; ++i) {
        f[i] = f[i - 1] * i % N;
    }
    return f[x] * inv((f[y] * f[x - y]) % N) % N;
}

ll sumx(ll x) {
    return (x * x + x) / 2;
}

