	for i := range A {
		A[i] = m.ni()
	}
	return A
}

func (m *Main) solve() {
	tc := m.ni()
	for tc > 0 {
		n := m.ni()
		A := m.na(n)

		D := make([][3]int64, n+1)

		for i := n - 1; i >= 0; i-- {
			u := A[i]
			zero := int64(1) + D[u][0]
			if u+1 <= n {
				zero += D[u+1][0]
			}
			if u+2 <= n {
				zero += D[u+2][1]
			}
			one := int64(1) + D[u][1]
			if u > 1 {
				one += D[u-2][2]
			}
			two := int64(1) + D[u][2]
			if u+2 <= n {
				two += D[u+2][1]
			}

			D[u][0] = (D[u][0] + zero) % mod
			D[u][1] = (D[u][1] + one) % mod
			D[u][2] = (D[u][2] + two) % mod
		}

		ans := (D[0][0] + D[1][1]) % mod
		fmt.Fprintln(m.out, ans)
		tc--
	}
	m.out.Flush()
}

func main() {
	in := bufio.NewScanner(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	mainObj := &Main{out: out, in: in}
	mainObj.solve()
}

