class Program
{
    private readonly StreamWriter _out = new StreamWriter(Console.OpenStandardOutput());
    private readonly StreamReader _in = new StreamReader(Console.OpenStandardInput());
    private string[] _tok = Array.Empty<string>();

    private string Next()
    {
        if (_tok.Length == 0) _tok = _in.ReadLine().Split();
        return _tok[0];
    }

    private int Ni() => int.Parse(Next());
    private long Nl() => long.Parse(Next());
    private int[] Na(int n)
    {
        int[] A = new int[n];
        for (int i = 0; i < n; i++) A[i] = Ni();
        return A;
    }

    private const long Mod = 998244353;

    private void Solve()
    {
        int tc = Ni();
        while (tc-- > 0)
        {
            int n = Ni();
            int[] A = Na(n);

            long[,] D = new long[n + 1, 3];

            for (int i = n - 1; i >= 0; i--)
            {
                int u = A[i];
                long zero = 1L + D[u, 0];
                if (u + 1 <= n) zero += D[u + 1, 0];
                if (u + 2 <= n) zero += D[u + 2, 1];
                long one = 1L + D[u, 1];
                if (u > 1) one += D[u - 2, 2];
                long two = 1L + D[u, 2];
                if (u + 2 <= n) two += D[u + 2, 1];

                D[u, 0] = (D[u, 0] + zero) % Mod;
                D[u, 1] = (D[u, 1] + one) % Mod;
                D[u, 2] = (D[u, 2] + two) % Mod;
            }

            long ans = (D[0, 0] + D[1, 1]) % Mod;
            _out.WriteLine(ans);
        }
        _out.Flush();
    }

    private int Dc(long a)
    {
        int r = 0;
        while (a > 0) { r++; a /= 10; }
        return r;
    }

    private int Gcd(int a, int b) => b == 0 ? a : Gcd(b, a % b);
    private long Gcd(long a, long b) => b == 0 ? a : Gcd(b, a % b);
    private long Mp(long a, long p)
    {
        long r = 1;
        while (p > 0)
        {
            if ((p & 1) == 1) r = (r * a) % Mod;
            p >>= 1;
            a = (a * a) % Mod;
        }
        return r;
    }

    static void Main(string[] args)
    {
        new Program().Solve();
    }
}

