impl FastReader {
    fn new() -> Self {
        FastReader {
            reader: io::BufReader::new(io::stdin()),
            buffer: String::new(),
        }
    }

    fn next(&mut self) -> Option<String> {
        if self.buffer.is_empty() {
            let mut line = String::new();
            self.reader.read_line(&mut line).expect("Failed to read line");
            self.buffer = line;
        }
        let pos = self.buffer.find(' ')?;
        let token = self.buffer[..pos].to_string();
        self.buffer.drain(..=pos);
        Some(token)
    }

    fn next_int(&mut self) -> i32 {
        self.next().unwrap().parse().expect("Failed to parse integer")
    }

    fn next_long(&mut self) -> i64 {
        self.next().unwrap().parse().expect("Failed to parse long")
    }

    fn next_double(&mut self) -> f64 {
        self.next().unwrap().parse().expect("Failed to parse double")
    }

    fn next_line(&mut self) -> String {
        let line = self.buffer.clone();
        self.buffer.clear();
        line.trim_end().to_string()
    }
}

