        return tok.removeFirst()
    }

    func ni() throws -> Int {
        return Int(try next())!
    }

    func nl() throws -> Int64 {
        return Int64(try next())!
    }

    func na(_ n: Int) throws -> [Int] {
        var A = [Int]()
        for _ in 0..<n {
            A.append(try ni())
        }
        return A
    }

    let mod: Int64 = 998244353

    func solve() throws {
        let tc = try ni()
        for _ in 1...tc {
            let n = try ni()
            let A = try na(n)

            var D = Array(repeating: Array(repeating: Int64(0), count: 3), count: n + 1)

            for i in stride(from: n - 1, through: 0, by: -1) {
                let u = A[i]
                let zero = (1 + D[u][0]) % mod
                if u + 1 <= n { D[u][0] = (D[u][0] + zero + D[u + 1][0]) % mod }
                if u + 2 <= n { D[u][0] = (D[u][0] + zero + D[u + 2][1]) % mod }
                let one = (1 + D[u][1]) % mod
                if u > 1 { D[u][1] = (D[u][1] + one + D[u - 2][2]) % mod }
                let two = (1 + D[u][2]) % mod
                if u + 2 <= n { D[u][2] = (D[u][2] + two + D[u + 2][1]) % mod }
            }

            let ans = (D[0][0] + D[1][1]) % mod
            out.write("\(ans)\n".data(using: .utf8)!)
        }
    }

    func dc(_ a: Int64) -> Int {
        var r = 0
        var aa = a
        while aa > 0 {
            r += 1
            aa /= 10
        }
        return r
    }

    func gcd(_ a: Int, _ b: Int) -> Int {
        return b == 0 ? a : gcd(b, a % b)
    }

    func gcd(_ a: Int64, _ b: Int64) -> Int64 {
        return b == 0 ? a : gcd(b, a % b)
    }

    func mp(_ a: Int64, _ p: Int64) -> Int64 {
        var r = Int64(1)
        var aa = a
        var pp = p
        while pp > 0 {
            if pp & 1 == 1 { r = (r * aa) % mod }
            pp >>= 1
            aa = (aa * aa) % mod
        }
        return r
    }
}

do {
    try Main().solve()
} catch {
    print(error)
}
